@DrlDefinition("customerInlineGreeting.drl")
public class CustomerInlineGreetingRuleSource {

    @DrlGlobal
    public CoredeuxComponentRegistry componentRegistry;

    @DrlRule(name = "greet", when = "$context : RuleContext(method == 'greet')")
    public void greet(RuleContext<String> $context) {
        $context.setOutput("Hello from inline DRL source");
        $context.setMessage("Inline DRL executed successfully.");
    }
}
